opts = {"A": "TVX", "B": "HJL", "C": "MOP", "D": "NPR"}
def gaps(w):
    return tuple(ord(b) - ord(a) for a, b in zip(w, w[1:]))
g = {k: gaps(v) for k, v in opts.items()}
match = [k for k in opts if sum(g[j] == g[k] for j in opts) == 1]
assert len(match) == 1
print(f"ANSWER={match[0]}")

opts = {"A": "Father's mother", "B": "Mother", "C": "Mother's mother", "D": "Father's sister"}
code = {"x": "mother", "-": "wife", "/": "father", "+": "sister"}
expr = [("H", "x", "I"), ("I", "-", "J"), ("J", "/", "K"), ("K", "+", "L")]
mother, father, wife, sibling = {}, {}, {}, {}
for a, op, b in expr:
    r = code[op]
    if r == "mother": mother[b] = a
    elif r == "father": father[b] = a
    elif r == "wife": wife[b] = a
    elif r == "sister": sibling[b] = a
# siblings share parents; a father's wife is the mother
for b, a in sibling.items():
    if a in father: father[b] = father[a]
    if a in mother: mother[b] = mother[a]
for c, f in list(father.items()):
    if f in wife and c not in mother: mother[c] = wife[f]
def path(target, person):
    for name, rel in (("Mother", mother), ("Father", father)):
        p = rel.get(person)
        if p == target: return name
        if p is not None:
            up = mother.get(p)
            if up == target: return f"{name}'s mother"
    return None
result = path("H", "L")
match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

from itertools import combinations
pts = {"A": (0, 10), "B": (-6, 0), "C": (6, 0), "O": (0, 6)}
segs = {frozenset(s) for s in ["AB", "BC", "CA", "AO", "BO", "CO"]}
def collinear(a, b, c):
    (x1, y1), (x2, y2), (x3, y3) = pts[a], pts[b], pts[c]
    return (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1) == 0
result = sum(1 for t in combinations(pts, 3)
             if all(frozenset(e) in segs for e in combinations(t, 2)) and not collinear(*t))
opts = {"A": 5, "B": 4, "C": 2, "D": 3}
match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

pat = "I__I_I__I_J_"
opts = {"A": "JIJIJII", "B": "JIIIJJI", "C": "IJIIJJI", "D": "IIJJJIJ"}
def fill(o):
    it = iter(o)
    return "".join(next(it) if c == "_" else c for c in pat)
def periodic(s):
    return any(len(s) % p == 0 and s == s[:p] * (len(s) // p) for p in range(2, len(s) // 2 + 1))
match = [k for k, v in opts.items() if periodic(fill(v))]
assert len(match) == 1
print(f"ANSWER={match[0]}")
